# Povești din Biblie: b002 Facerea lumii, b003 David și Goliat, b004 Iona și peștele cel mare
def build(sid,frm,ch,TI,SC,T,QZ):
    for l in T: assert len(T[l])==len(SC),(sid,l)
    sc=[]
    for i,x in enumerate(SC):
        d={'bg':x[0],'c':x[1],'w':x[2],'t':{l:T[l][i] for l in T}}
        if x[3]:d['n']=x[3]
        if x[4]:d['fx']=x[4]
        sc.append(d)
    return {'id':sid,'from':frm,'ch':ch,'acc':'','title':TI,'sc':sc,'qz':QZ}

